import React, { useState } from 'react';
import { Alert, Keyboard, View } from 'react-native';
import useCSS from '@src/presentation/style';
import { ActionButton, Spacer, PinInput, Text, LoadingBlockerView } from '@core/ui';
import { useTranslation } from 'react-i18next';
import { useDispatch } from '@src/lib/redux';
import { SubmitLoanProposalPayload } from '@src/application/loan_collateral/queries/submit_loan_proposal/submit_loan_proposal_query';
import { fetchSubmitLoanProposal } from '../thunk';
import { SubmitLoanProposalResponse } from '@src/domain/entities/loan_collateral/submit_loan_proposal';
import { MainStackNavigationProp } from '@src/presentation/navigation/MainNavigator';
import { useNavigation } from '@react-navigation/native';

interface Props {
    payload: SubmitLoanProposalPayload['data'];
    onSubmit: () => void;
}

const ContentOTP: React.FC<Props> = ({ payload, onSubmit }) => {
    const navigation = useNavigation<MainStackNavigationProp>();
    const css = useCSS();
    const dispatch = useDispatch();
    const { t } = useTranslation(['module_collateral']);
    const [loading, setLoading] = useState(false);

    const handleChange = (otp: string) => {
        if (otp.length >= 6) {
            setLoading(true);
            payload.otp = otp;
            dispatch(fetchSubmitLoanProposal(payload))
                .then((res) => {
                    if ((res?.payload as SubmitLoanProposalResponse).resultCode === '00') {
                        setLoading(false);
                        navigation.navigate('collateral_result');
                        onSubmit?.();
                        Keyboard.dismiss();
                    }
                })
                .catch((err) => {
                    setLoading(false);
                    Alert.alert('Thông báo', err);
                });
        }
    };

    return (
        <>
            {loading && <LoadingBlockerView containerStyle={{ backgroundColor: 'rgba(255,255,255,0.5)', zIndex: 100000 }} />}
            <View style={[css.items_center]}>
                <PinInput cellCount={6} onChange={handleChange} />
            </View>
            <Spacer height={32} />
            <ActionButton title={t('screen_confirm.bs_otp_resend')} type='error' onPress={() => {}} />
        </>
    );
};

export default ContentOTP;
