import { createAsyncThunk } from '@reduxjs/toolkit';
import { GetWeatherHandler } from '@src/application/weather/queries/get_weather/get_weather_handler';
import { TYPES } from '@src/di/types/types';
import { container } from '@src/di/inversify.config';
import { Query } from '@src/domain/models/query';
import { GetWeatherQuery } from '@src/application/weather/queries/get_weather/get_weather_query';

export const fetchWeather = createAsyncThunk(
  'weather/fetch',
  async (request: GetWeatherQuery) => {
    const weather = container.get<GetWeatherHandler>(TYPES.GetWeatherHandler);

    const query = new Query({
      query: { latitude: request.latitude, longitude: request.longitude },
    });
    return await weather.handle(query);
  },
);
