import { TYPES } from '@src/di/types/types';
import type { IGetListCurrentAccountsRepository } from '@src/domain/interfaces/loan_collateral/get_list_current_accounts';
import { inject } from 'inversify';
import { GetListCurrentAccountsPayload } from './get_list_current_accounts_query';

export class GetListCurrentAccountsHandler {
    private readonly _getListCurrentAccountsRepository: IGetListCurrentAccountsRepository;

    constructor(@inject(TYPES.IGetListCurrentAccountsRepository) getListCurrentAccountsRepository: IGetListCurrentAccountsRepository) {
        this._getListCurrentAccountsRepository = getListCurrentAccountsRepository;
    }

    handler(dataRequest: GetListCurrentAccountsPayload) {
        return this._getListCurrentAccountsRepository.getListCurrentAccounts(dataRequest);
    }
}
