import { TYPES } from '@src/di/types/types';
import { Query } from '@src/domain/models/query';
import { inject } from 'inversify';
import type { IClientInfoRepository } from '@src/domain/interfaces/common/clientInfo';
import { GetClientInfoPayload } from './get_client_info_payload';

export class GetClientInfoHandler {
    private readonly _clientInfoRepository: IClientInfoRepository;

    constructor(
        @inject(TYPES.IClientInfoRepository) clientInfoRepository: IClientInfoRepository,
    ) {
        this._clientInfoRepository = clientInfoRepository;
    }

    handle(query: Query<GetClientInfoPayload>) {
        return this._clientInfoRepository.getClientInfo(query);
    }
}
