import { TYPES } from '@src/di/types/types';
import { Query } from '@src/domain/models/query';
import { inject } from 'inversify';
import type { ILoanDemandRepository } from '@src/domain/interfaces/loan_register/loanDemand';
import { RegisterLoanDemandPayload } from '@src/domain/entities/loan_register/loanDemand';

export class RegisterLoanDemandHandler {
    private readonly _loanDemandRepository: ILoanDemandRepository;

    constructor(
        @inject(TYPES.ILoanDemandRepository) loanDemandRepository: ILoanDemandRepository,
    ) {
        this._loanDemandRepository = loanDemandRepository;
    }

    handle(query: Query<RegisterLoanDemandPayload>) {
        return this._loanDemandRepository.registerLoanDemand(query);
    }
}
