import { View, Text } from 'react-native'
import React, { useEffect, useState } from 'react'
import useCSS from '../../style';
import { createStyles, Theme, useTheme } from '@core/ui';
import { useSharedValue } from 'react-native-reanimated';
import { Slider } from 'react-native-awesome-slider';
const thumbWidth = 20;
const bubbleWidth = 90;
interface SliderProgressProps {
    min: number;
    max: number;
    onChange: (value: number) => void;
    value: number;
}
const SliderProgress = (props: SliderProgressProps) => {
    const css = useCSS()
    const styles = useStyles()
    const { theme } = useTheme()
    const progress = useSharedValue(props.value);
    const min = useSharedValue(props.min);
    const max = useSharedValue(props.max);
    const [currentValue, setCurrentValue] = useState(0);
    useEffect(() => {
        progress.value = props.value;
    }, [props.value]);
    return (
        <View style={{ paddingTop: 35 }}>
            <Slider
                progress={progress}
                style={styles.slider}
                minimumValue={min}
                maximumValue={max}
                bubbleWidth={bubbleWidth}
                bubbleMaxWidth={bubbleWidth}
                bubbleTranslateY={-25}
                bubbleOffsetX={5}
                thumbWidth={thumbWidth}
                renderThumb={() => <View style={styles.customThumb} />}
                renderBubble={() => <View style={styles.customBubble}><Text style={{ ...theme.Typography.TextSubheadline.SemiBold, color: theme.Colors.Text.Error }}>{currentValue} năm</Text></View>}
                onValueChange={(value) => {
                    let rounded = Math.round(value);
                    setCurrentValue(rounded);
                    props?.onChange?.(rounded)
                }}
                theme={{
                    maximumTrackTintColor: '#F2F2F4',
                    minimumTrackTintColor: '#BE1128',
                    bubbleTextColor: '#262C36',
                    cacheTrackTintColor: 'rgba(189, 186, 186, 0.6)',
                }}
            />
        </View>
    )
}
const useStyles = createStyles((theme: Theme) => ({
    slider: {
        marginBottom: 20,
        marginTop: 12,
        color: 'red',
        height: 500,
    },
    customThumb: {
        width: thumbWidth,
        height: thumbWidth,
        borderRadius: 100,
        overflow: 'hidden',
        backgroundColor: '#FFFFFF',
        shadowColor: "#000",
        shadowOffset: { width: 5, height: 5 },
        shadowOpacity: 0.3,
        shadowRadius: 6,
        elevation: 8,
    },
    customBubble: {
        alignItems: 'center',
        width: bubbleWidth,
        backgroundColor: '#FFFFFF',
        borderRadius: 4,
    },
    bubbleImg: {
        width: 90,
        borderRadius: 4,
        height: 60,
    },
}));

export default SliderProgress